package com.propverse.ui;
import com.propverse.dao.RecordDAO;import javax.swing.*;import java.awt.*;import java.util.function.Consumer;
public class DashboardFrame extends JFrame {
 private final JLabel counts=new JLabel();
 public DashboardFrame(Consumer<Void> logout){super("PropVerse — Build Better. Manage Better.");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1050,700);setLocationRelativeTo(null);setLayout(new BorderLayout());JPanel side=new JPanel(new GridLayout(0,1,5,5));side.setBackground(new Color(32,48,65));side.setBorder(BorderFactory.createEmptyBorder(15,10,15,10));add(side,BorderLayout.WEST);JTabbedPane tabs=new JTabbedPane();tabs.addTab("Projects",new ModuleFrame(RecordDAO.PROJECT));tabs.addTab("Tasks",new ModuleFrame(RecordDAO.TASK));tabs.addTab("Workers",new ModuleFrame(RecordDAO.WORKER));tabs.addTab("Issues",new ModuleFrame(RecordDAO.ISSUE));tabs.addChangeListener(e->{if(tabs.getSelectedComponent() instanceof ModuleFrame module)module.refreshLookups();});JPanel home=new JPanel(new BorderLayout(12,12));JLabel title=new JLabel("Build Better. Manage Better.");title.setFont(new Font("SansSerif",Font.BOLD,27));home.add(title,BorderLayout.NORTH);counts.setFont(new Font("SansSerif",Font.PLAIN,20));home.add(counts,BorderLayout.CENTER);JButton refresh=new JButton("Refresh dashboard");refresh.addActionListener(e->refreshCounts());home.add(refresh,BorderLayout.SOUTH);tabs.insertTab("Dashboard",null,home,null,0);add(tabs,BorderLayout.CENTER);for(int i=1;i<tabs.getTabCount();i++){final int n=i;JButton b=new JButton(tabs.getTitleAt(i));b.addActionListener(e->tabs.setSelectedIndex(n));side.add(b);}JButton db=new JButton("Dashboard");db.addActionListener(e->{tabs.setSelectedIndex(0);refreshCounts();});side.add(db);JButton out=new JButton("Logout");out.addActionListener(e->{dispose();logout.accept(null);});side.add(out);refreshCounts();}
 private void refreshCounts(){try{var m=new RecordDAO().counts();StringBuilder s=new StringBuilder("<html><table cellpadding='18'>");for(var e:m.entrySet())s.append("<tr><td>").append(e.getKey()).append("</td><td><b>").append(e.getValue()).append("</b></td></tr>");counts.setText(s.append("</table></html>").toString());}catch(Exception e){counts.setText("Database error: "+e.getMessage());}}
}
